    ["Conjure Water"] = { id = 5504, tr = "must", c = "everyone", p = "current", r = "Держите усиление на себе, питьё и еду подходящими вашему уровню.", b = "Классический гайд советует 5-й ранг на 40 уровне для лучшего восстановления. В Forever есть услуга на 40 уровне; точное название смотрите в рангах клиента и подсказках.", ok = true },
    ["Counterspell"] = { id = 2139, tr = "must", c = "everyone", p = "learn", r = "Контроль, прерывание, снятие эффектов и отход нужны в любом древе.", ok = true },
    ["Dampen Magic"] = { id = 604, tr = "skip", c = "skip", p = "defer", r = "Покупайте только под запланированный магический урон; оно также ослабляет входящее лечение.", ok = true },
    ["Detect Magic"] = { tr = "skip", c = "skip", p = "defer", r = "Только старое название: сверьте с данными тренера Forever, прежде чем показывать совет." },
    ["Evocation"] = { id = 12051, tr = "must", c = "everyone", p = "learn", r = "Восстановление маны полезно любой школе." },
    ["Fire Blast"] = { id = 2136, tr = "nice", c = "nice", p = "used", r = "Мгновенное добивание для любого древа; берите ранги, если пользуетесь им постоянно.", k = "Улучшайте, пока добиваете им цели; школа огня не ограничивает изучение и совет древом огня.", ok = true },
    ["Fire Ward"] = { id = 543, tr = "skip", c = "skip", p = "defer", r = "Покупайте только под известный опасный урон огнём; в обычной прокачке не нужно.", ok = true },
    ["Fireball"] = { id = 143, tr = { ["Arcane"] = "nice", ["Fire"] = "must", ["Frost"] = "skip" }, c = "spec", t = { "Fire" }, p = "current", r = "Основная атака огня; гибриды с «Тайной магией» могут её использовать, а лёд может отложить поздние ранги.", k = "Стартовая атака необходима до появления «Ледяной стрелы» или другой основной; держите актуальным то заполнение, которым пользуетесь.", b = "До изучения «Ледяной стрелы» это ваш стартовый урон даже на будущем маршруте льда. Классический гайд огня советует 5-й ранг на 24; поздним сборкам льда можно не брать ненужные ранги «Огненного шара».", ok = true },
    ["Flamestrike"] = { id = 2120, tr = { ["Arcane"] = "nice", ["Fire"] = "nice", ["Frost"] = "skip" }, c = "nice", t = { "Arcane", "Fire" }, p = "used", r = "Улучшайте для запланированного урона огнём или тайной магией по площади; обычному льду по одной цели можно пропустить.", k = "Стиль боя по площади может оправдать это и в других древах; не советуйте бои по площади только из-за категории.", ok = true },
    ["Frost Armor"] = { id = 7300, tr = "must", c = "everyone", p = "used", r = "Используйте усиление брони; не тратьте на старую линейку, когда выбранная броня её заменяет.", k = "Держите активной одну броню. Не покупайте устаревшие ранги «Морозной брони» после замены на подходящую позднюю.", ok = true },
    ["Frost Blast"] = { id = 1326053, tr = { ["Arcane"] = "nice", ["Fire"] = "nice", ["Frost"] = "must" }, c = "spec", t = { "Frost" }, p = "used", r = "Ледяное заклинание на 1,5 секунды, замедляет на 40% и использует таланты «Ледяной стрелы»: основа льда и средство для боя на отходе для остальных.", b = "Новое заклинание 24 уровня с 15 октября; также может запускать «Залп снарядов» (исправление 16 октября)." },
    ["Frost Nova"] = { id = 122, tr = "must", c = "everyone", p = "learn", r = "Учите удержание в любой сборке; поздние ранги урона не улучшают его основную задачу контроля.", b = "Удержание работает с 1-го ранга. С 8 октября низкий ранг получает меньше от силы заклинаний и реже запускает таланты вроде «Обморожения», поэтому сборке льда, которая на них опирается, стоит держать ранг актуальным.", ok = true },
    ["Frost Ward"] = { id = 6143, tr = "skip", c = "skip", p = "defer", r = "Покупайте только под известный опасный урон льдом; в обычной прокачке не нужно.", ok = true },
    ["Frostbolt"] = { id = 116, tr = { ["Arcane"] = "nice", ["Fire"] = "skip", ["Frost"] = "must" }, c = "spec", t = { "Frost" }, p = "current", r = "Основная атака льда; огонь может держать низкий ранг только ради замедления, гибриды с тайной магией — актуальный.", k = "Учите раннее замедление в любом древе; ранги урона улучшайте, когда лёд — ваша основная атака.", b = "Классический гайд льда советует 4-й ранг на 20 и 5-й на 26; огонь может держать 1-й ранг для быстрого замедления: с 8 октября такой низкий ранг всё ещё замедляет, но почти не получает силы заклинаний и не запускает таланты льда (пример самой Blizzard).", ok = true },
    ["Frostfire Bolt"] = { id = 401502, tr = { ["Arcane"] = "skip", ["Fire"] = "nice", ["Frost"] = "nice" }, c = "nice", t = { "Fire", "Frost" }, p = "used", r = "Замеченные улучшения Forever; берите в первую очередь, только если сборка действительно использует этот гибридный удар.", ok = true },
    ["Ice Armor"] = { id = 7302, tr = "must", c = "everyone", p = "used", r = "Физическая защита подходит для частых ближних боёв; активна может быть только одна броня.", k = "Держите активной одну броню; она заменяет «Морозную броню», а не складывается с ней. Если маршруту больше подходит восстановление маны, используйте «Магическую броню».", b = "Классическая физическая броня появляется на 30; выбирайте её или «Магическую броню» на 34 по стилю боя, а не покупайте все варианты.", ok = true },
    ["Ice Barrier"] = { id = 13031, tr = { ["Arcane"] = "skip", ["Fire"] = "skip", ["Frost"] = "must" }, c = "spec", t = { "Frost" }, p = "current", r = "Защитное умение льда; замеченные платные ранги Forever стоит брать в первую очередь после изучения.", b = "Классический гайд льда берёт 2-й ранг на 46, 3-й на 52 и 4-й на 58. Платные услуги Forever на этих уровнях замечены, но требование таланта и точные названия рангов нужно проверять отдельно.", ok = true },
    ["Ice Block"] = { id = 11958, tr = { ["Arcane"] = "skip", ["Fire"] = "skip", ["Frost"] = "must" }, c = "spec", t = { "Frost" }, p = "learn", r = "Важный аварийный сброс льда после изучения." },
    ["Ice Lance"] = { id = 400640, tr = { ["Arcane"] = "skip", ["Fire"] = "skip", ["Frost"] = "must" }, c = "spec", t = { "Frost" }, p = "current", r = "Замеченные улучшения льда в Forever; берите в первую очередь, если она входит в ротацию по замороженным целям.", ok = true },
    ["Mage Armor"] = { id = 6117, tr = "nice", c = "nice", p = "used", r = "Восстановление помогает заклинателю в бою на отходе; выбирайте её вместо физической брони, когда это подходит вашим боям.", k = "Держите активной одну броню. «Морозная броня» или «Ледяная броня» остаются полезным защитным выбором; держать все варианты необязательно.", b = "В Classic впервые изучается на 34; восстановление полезно для боя на отходе, а при частом уроне по площади лучше подойдёт «Ледяная броня». Услуга 34 уровня в Forever замечена.", ok = true },
    ["Mana Shield"] = { id = 1463, tr = "nice", c = "nice", p = "used", r = "Аварийная защита тратит ману; улучшайте, если частые удары или бои с пачками заставляют вас её использовать.", ok = true },
    ["Polymorph"] = { id = 118, tr = "must", c = "everyone", p = "learn", r = "Учите контроль в любой сборке; улучшайте для более долгого контроля, когда бои этого требуют.", b = "Классический 2-й ранг на 20 даёт более долгий контроль; на 40 — 3-й ранг, а не 2-й. Улучшение на 40 полезно для более долгого удержания, но это не подтверждённое требование к уровню цели. Услуга 40 уровня в Forever замечена; точный ранг у тренера ещё проверяется.", ok = true },
    ["Polymorph: Cow"] = { id = 28270, tr = "skip", c = "skip", p = "defer", r = "Выбор внешнего вида; обычное «Превращение» даёт контроль для прокачки." },
    ["Polymorph: Pig"] = { tr = "skip", c = "skip", p = "defer", r = "Выбор внешнего вида; обычное «Превращение» даёт контроль для прокачки." },
